using namespace std;

struct Fraction {
    long long numerator, denominator;
};

pair<long long, long long> get_fraction_bounds(int x, int y, int b) {
    long long min_val = (long long)b * x / y;
    long long max_val = ((long long)b * x + y - 1) / y;
    return {min_val, max_val};
}

long long gcd_ll(long long a, long long b) {
    while (b != 0) {
        long long t = b;
        b = a % b;
        a = t;
    }
    return a;
}

void find_closest_fraction_value(int x, int y, int n) {
    vector<Fraction> candidates;
    for (int b = 1; b <= n; ++b) {
        auto bounds = get_fraction_bounds(x, y, b);
        candidates.push_back({bounds.first, b});
        candidates.push_back({bounds.second, b});
    }

    auto compare_fraction = [&](Fraction f1, Fraction f2) {
        long long diff1 = abs((long long)x * f1.den * f2.den - f1.num * f2.den * y);
        long long diff2 = abs((long long)x * f1.den * f2.den - f2.num * f1.den * y);
        if (diff1 != diff2) return diff1 < diff2;
        if (f1.den != f2.den) return f1.den < f2.den;
        return f1.num < f2.num;
    };

    sort(candidates.begin(), candidates.end(), compare_fraction);
    cout << candidates.front().num << "/" << candidates.front().den << "\n";
}

