import java.util.*;
import java.io.*;

public class Main {
    static class Fraction {
        long numerator, denominator;
        Fraction(long numerator, long denominator) {
            this.numerator = numerator;
            this.denominator = denominator;
        }
    }

    static long[] getFractionBounds(int x, int y, int b) {
        long minVal = (long) b * x / y;
        long maxVal = ((long) b * x + y - 1) / y;
        return new long[]{minVal, maxVal};
    }

    static long gcdLL(long a, long b) {
        while (b != 0) {
            long t = b;
            b = a % b;
            a = t;
        }
        return a;
    }

    static void findClosestFractionValue(int x, int y, int n) {
        List<Fraction> candidates = new ArrayList<>();
        for (int b = 1; b <= n; b++) {
            long[] bounds = getFractionBounds(x, y, b);
            candidates.add(new Fraction(bounds[0], b));
            candidates.add(new Fraction(bounds[1], b));
        }

        candidates.sort((f1, f2) -> {
            long diff1 = Math.abs((long) x * f1.denominator - f1.numerator * y);
            long diff2 = Math.abs((long) x * f2.denominator - f2.numerator * y);
            if (diff1 != diff2) return Long.compare(diff1, diff2);
            if (f1.denominator != f2.denominator) return Long.compare(f1.denominator, f2.denominator);
            return Long.compare(f1.numerator, f2.numerator);
        });

        Fraction best = candidates.get(0);
        System.out.println(best.numerator + "/" + best.denominator);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int x = Integer.parseInt(parts[0]);
        int y = Integer.parseInt(parts[1]);
        int n = Integer.parseInt(parts[2]);
        findClosestFractionValue(x, y, n);
    }
}
